// Parse scored listings and format for email
const items = $input.all();
let listings = [];

// The file content comes as binary or text
for (const item of items) {
  if (item.json.data) {
    try {
      listings = JSON.parse(item.json.data);
    } catch(e) {}
  }
  if (item.json.content) {
    try {
      listings = JSON.parse(item.json.content);
    } catch(e) {}
  }
}

// Fallback: try reading from the binary property
if (listings.length === 0) {
  for (const item of items) {
    if (item.binary && item.binary.data) {
      const content = Buffer.from(item.binary.data.data, 'base64').toString('utf-8');
      try {
        listings = JSON.parse(content);
      } catch(e) {}
    }
  }
}

if (listings.length === 0) {
  return [{ json: { subject: 'Baubau Deal Finder — Tidak ada deal hari ini', body: '<h2>Tidak ada deal menarik hari ini.</h2>', hasDeals: false } }];
}

const great = listings.filter(l => l.score_label === 'great_deal');
const good = listings.filter(l => l.score_label === 'good_deal');
const fair = listings.filter(l => l.score_label === 'fair_deal');

const today = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });

let body = `
<h2 style="color:#333;">Baubau Deal Finder — ${today}</h2>
<p>Ditemukan <strong>${listings.length}</strong> deal: ${great.length} great, ${good.length} good, ${fair.length} fair.</p>
`;

const renderCards = (label, emoji, items, color) => {
  if (items.length === 0) return '';
  let html = `<h3>${emoji} ${label}</h3>`;
  for (const item of items) {
    const title = (item.title || 'Tanpa judul').substring(0, 80);
    const price = item.asking_price || 0;
    const ref = item.reference_price || 0;
    const savings = item.savings || 0;
    const savingsPct = item.savings_pct || 0;
    const condition = {new:'Baru',like_new:'Seperti Baru',used:'Bekas'}[item.condition] || item.condition;
    const cat = item.category_name || '-';
    const url = item.url || '#';
    const group = item.group_name || item.source || '-';
    const score = item.score || 0;

    html += `
    <div style="border-left:5px solid ${color};padding:12px;margin:8px 0;background:#f9f9f9;border-radius:4px;">
      <span style="font-size:20px;font-weight:bold;color:${color};">${score.toFixed(0)}</span>
      <h4 style="margin:4px 0;"><a href="${url}">${title}</a></h4>
      <p style="color:#e91e63;font-weight:bold;">Rp${price.toLocaleString('id-ID')} <span style="text-decoration:line-through;color:#999;">Rp${ref.toLocaleString('id-ID')}</span></p>
      <p style="color:#4CAF50;">Hemat Rp${savings.toLocaleString('id-ID')} (${savingsPct.toFixed(0)}% off) — Kondisi: ${condition}</p>
      <p style="color:#666;font-size:0.9em;">Kategori: ${cat} | Grup: ${group}</p>
    </div>`;
  }
  return html;
};

body += renderCards('Great Deal', '🔥', great, '#4CAF50');
body += renderCards('Good Deal', '👍', good, '#2196F3');
body += renderCards('Fair Deal', '💡', fair, '#FF9800');

body += `
<hr style="margin-top:20px;">
<p style="color:#999;font-size:0.8em;">Dikirim oleh Baubau Deal Finder | Dari Facebook Groups Baubau</p>
`;

const subject = `Baubau Deal Finder — ${listings.length} deal menarik ditemukan`;

return [{ json: { subject, body, hasDeals: true, count: listings.length } }];
